import * as T from './vendor/three.module.js';
import {regionPoints} from './region-tools.js?v=depot-v17';
import {DepthRenderer} from './chess-engine.js?v=depot-v17';
import {cityCamera,eased} from './city-motion.js?v=depot-v17';
export function createCityEngine(){let renderer;try{renderer=new T.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setSize(960,540);renderer.outputColorSpace=T.SRGBColorSpace}catch{renderer=new DepthRenderer();renderer.maxTextureSize=1536}const scene=new T.Scene();scene.background=new T.Color('#08131c');const camera=new T.PerspectiveCamera(42,16/9,.02,200),source=document.createElement('canvas');source.width=1536;source.height=1536;const c=source.getContext('2d'),texture=new T.CanvasTexture(source);texture.colorSpace=T.SRGBColorSpace;const plane=new T.Mesh(new T.PlaneGeometry(30,30),new T.MeshBasicMaterial({map:texture,color:'#ffffff',side:T.DoubleSide}));plane.rotation.x=-Math.PI/2;scene.add(plane);const ray=new T.Raycaster();let lastKey='';
function paint(ctx,age,fx,media,logoImage=null){const cam=cityCamera(age,fx),alphas=(fx.cityRegions||[]).map(l=>eased((age-(l.start??fx.cityLogoStart))/Math.max(.1,l.fade??fx.cityLogoFade))),key=JSON.stringify([fx.cityRegions,alphas,cam.logo,cam.spin,fx.cityLogoSize,fx.cityLogoU,fx.cityLogoV,fx.cityLogoTurns,logoImage?.src,media.src,media.currentTime||0]);if(key!==lastKey){lastKey=key;c.clearRect(0,0,1536,1536);if(fx.preserveAspect){const iw=media.videoWidth||media.naturalWidth||media.width,ih=media.videoHeight||media.naturalHeight||media.height,s=Math.min(1536/iw,1536/ih);c.drawImage(media,(1536-iw*s)/2,(1536-ih*s)/2,iw*s,ih*s)}else c.drawImage(media,0,0,1536,1536);const regions=fx.cityRegions||[];for(const [index,layer] of regions.entries()){const points=regionPoints(layer);if(layer.visible===false||points.length<3)continue;c.save();c.beginPath();points.forEach(([u,v],i)=>i?c.lineTo(u*1536,v*1536):c.moveTo(u*1536,v*1536));c.closePath();c.globalAlpha=alphas[index]*(layer.opacity??.3);c.globalCompositeOperation=layer.blend||'color';c.fillStyle=layer.color;c.fill();c.globalCompositeOperation='source-over';c.globalAlpha=alphas[index]*.6;c.strokeStyle=layer.color;c.lineWidth=2;c.stroke();c.restore()}if(cam.logo>0){c.save();c.translate(fx.cityLogoU*1536,fx.cityLogoV*1536);c.rotate(cam.spin*fx.cityLogoTurns*Math.PI*2);c.scale(fx.cityLogoSize,fx.cityLogoSize);c.globalAlpha=cam.logo;c.fillStyle=fx.cityLogoColor;if(logoImage?.complete&&logoImage.naturalWidth){const ratio=logoImage.naturalHeight/logoImage.naturalWidth;c.drawImage(logoImage,-120,-120*ratio,240,240*ratio)}else for(let i=0;i<3;i++){c.save();c.translate((i-1)*58,0);c.rotate(-.45);c.fillRect(-23,-35-i*26,46,85+i*26);c.restore()}c.restore()}texture.needsUpdate=true;renderer.textures?.delete(texture)}camera.position.fromArray(cam.position);camera.up.set(0,1,0);camera.lookAt(new T.Vector3(...cam.target));camera.rotateZ(cam.roll);camera.updateMatrixWorld(true);renderer.render(scene,camera);ctx.drawImage(renderer.domElement,0,0,960,540);return cam}
function pick(u,v){ray.setFromCamera(new T.Vector2(u*2-1,1-v*2),camera);const hit=ray.intersectObject(plane)[0];return hit?{u:hit.uv.x,v:1-hit.uv.y}:null}
return{paint,pick,software:!!renderer.software}}
